(function(window){var RecaptchaForm=function(){};RecaptchaForm.siteKey='';RecaptchaForm.recaptchaLoaded=false;RecaptchaForm.recaptchaLoading=false;RecaptchaForm.recaptchaCallbacks=[];RecaptchaForm.init=function(){var forms=document.querySelectorAll('form[onsubmit*="RecaptchaForm.submit"]');if(forms.length===0){return;}
forms.forEach(function(form){var inputs=form.querySelectorAll('input, textarea, select');var loadRecaptcha=function(){if(!RecaptchaForm.recaptchaLoaded&&!RecaptchaForm.recaptchaLoading){RecaptchaForm.loadGoogleRecaptcha();}};inputs.forEach(function(input){input.addEventListener('focus',loadRecaptcha,{once:true});input.addEventListener('click',loadRecaptcha,{once:true});});var submitButton=form.querySelector('button[type="submit"], input[type="submit"]');if(submitButton){submitButton.addEventListener('click',loadRecaptcha,{once:true});}});};RecaptchaForm.loadGoogleRecaptcha=function(){if(RecaptchaForm.recaptchaLoaded||RecaptchaForm.recaptchaLoading){return;}
if(!RecaptchaForm.siteKey){console.warn('RecaptchaForm: siteKey is not set');return;}
RecaptchaForm.recaptchaLoading=true;if(document.querySelector('script[src*="google.com/recaptcha/api.js"]')){RecaptchaForm.waitForRecaptcha();return;}
var script=document.createElement('script');script.src='https://www.google.com/recaptcha/api.js?render='+RecaptchaForm.siteKey;script.async=true;script.defer=true;script.onload=function(){RecaptchaForm.recaptchaLoaded=true;RecaptchaForm.recaptchaLoading=false;RecaptchaForm.recaptchaCallbacks.forEach(function(callback){callback();});RecaptchaForm.recaptchaCallbacks=[];};script.onerror=function(){RecaptchaForm.recaptchaLoading=false;console.error('RecaptchaForm: Failed to load Google reCAPTCHA script');};document.head.appendChild(script);};RecaptchaForm.waitForRecaptcha=function(){var checkInterval=setInterval(function(){if(typeof window.grecaptcha!=='undefined'&&window.grecaptcha.ready){clearInterval(checkInterval);RecaptchaForm.recaptchaLoaded=true;RecaptchaForm.recaptchaLoading=false;RecaptchaForm.recaptchaCallbacks.forEach(function(callback){callback();});RecaptchaForm.recaptchaCallbacks=[];}},100);setTimeout(function(){clearInterval(checkInterval);if(!RecaptchaForm.recaptchaLoaded){RecaptchaForm.recaptchaLoading=false;console.error('RecaptchaForm: Timeout waiting for Google reCAPTCHA');}},10000);};RecaptchaForm.ensureRecaptchaLoaded=function(callback){if(RecaptchaForm.recaptchaLoaded){callback();return;}
RecaptchaForm.recaptchaCallbacks.push(callback);if(!RecaptchaForm.recaptchaLoading){RecaptchaForm.loadGoogleRecaptcha();}};RecaptchaForm.submit=function(event,form){event.preventDefault();event.stopPropagation();var validator=$(form).validate(window.validationRules);let dialCodeValid=true;if($(form).find('input[type="tel"]').length){if(!$(form).find('.selected-dial-code').length||!$(form).find('.selected-dial-code').text().length||$(form).find('.selected-dial-code').text()=='00'){dialCodeValid=false;const $field=$(form).find('input[type="tel"]');$field.parents('.field').first().removeClass('state-success').addClass('state-error');if($field.parents('.field').find('em.state-error').length){$field.parents('.field').find('em').text('Kies uw land.').show();}else{$field.parents('.field').append(`<em for="${$field.prop('id')}"class="state-error">Klik op 00 en kies een nummer</em>`);}}}
if(!validator.form()||!dialCodeValid){return;}
RecaptchaForm.ensureRecaptchaLoaded(function(){grecaptcha.ready(function(){grecaptcha.execute(RecaptchaForm.siteKey,{action:'submit'}).then(function(token){$(form).find('input[name="recaptcha-token"]').val(token);form.submit();}).catch(function(){form.submit();});});});};RecaptchaForm.executeGoogleRecaptcha=function(form,callback){RecaptchaForm.ensureRecaptchaLoaded(function(){grecaptcha.ready(function(){grecaptcha.execute(RecaptchaForm.siteKey,{action:'submit'}).then(function(token){$(form).find('input[name="recaptcha-token"]').val(token);callback();}).catch(function(){callback();});});});};window.RecaptchaForm=RecaptchaForm;if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',function(){RecaptchaForm.init();});}else{RecaptchaForm.init();}})(window);;